import{_ as e,o as a,b as p,q as r}from"./chunks/framework.Tf23FRXt.js";const O=JSON.parse('{"title":"万魔殿 炼净之狱4","description":"","frontmatter":{},"headers":[],"relativePath":"duty/883.htm.md","filePath":"duty/883.md","lastUpdated":1791098838000}'),_={name:"duty/883.htm.md"};function d(o,t,s,i,n,S){return a(),p("div",null,[...t[0]||(t[0]=[r('<h1 id="万魔殿-炼净之狱4" tabindex="-1">万魔殿 炼净之狱 4</h1><p>BOSS 读条<mark>创兽炎舞</mark>的同时，周身会出现鸟或龙：</p><ul><li>出现龙：中央直线 AOE，前往 BOSS 两侧躲避</li><li>出现鸟：两侧 AOE，在 BOSS 脚下躲避。<br> AOE 范围在地面上有隐约可见的黑色细线，看不清的话建议两侧到 BOSS 外，中央在 BOSS 正下方躲避。</li></ul><p>地面出现 2 个移动的眼睛图标：背对眼睛图标，机制判定后会蹦出 2 个小怪，需要及时击杀。</p><p>四角出现距离衰减 AOE 提示时，站在场地中央处理。之后 BOSS 会连线其中两个角，被连线的角落会发出超大范围的圆形 AOE，在中场稍微靠后的位置躲避，之后会有 2 条龙从连线的火滩中跃出，跳至任意 2 个火滩中，并再次引发圆形 AOE，注意观察动画特效躲避。</p><p>之后场地会连续出现 3 次击退预兆，会按照预兆的顺序依次释放击退，注意尽量让自己每次都能被击退到下一个击退的起点。</p><p>场地上出现蓝色火焰时注意观察，蓝色火焰会围出一个矩形区域，所有被围起来的区域都将有 AOE。</p><p>之后是上述机制的组合机制。</p>',8)])])}const m=e(_,[["render",d]]);export{O as __pageData,m as default};
